public class StarvationBarging {
    static final Object lock = new Object();
    static volatile boolean victimDone = false;
    static int served = 0;

    static class Greedy extends Thread {
        public void run() {
            // re-acquires the lock in a tight loop; never yields to the victim on purpose
            while (!victimDone) {
                synchronized (lock) {
                    served++;
                }
            }
        }
    }

    static class Victim extends Thread {
        public void run() {
            // needs the lock once, but the intrinsic lock is not fair
            synchronized (lock) {
                victimDone = true;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread greedy = new Greedy();
        Thread victim = new Victim();
        greedy.start();
        victim.start();
        greedy.join();
        victim.join();
    }
}

import java.util.LinkedList;

public class PriorityStarvation {
    static final LinkedList<Integer> high = new LinkedList<Integer>();
    static final LinkedList<Integer> low = new LinkedList<Integer>();
    static volatile boolean lowServed = false;

    static class Producer extends Thread {
        public void run() {
            int i = 0;
            // keeps the high-priority queue non-empty
            while (!lowServed) {
                synchronized (high) {
                    if (high.size() < 2) {
                        high.add(i++);
                    }
                }
            }
        }
    }

    static class Server extends Thread {
        public void run() {
            // strict priority: low-priority work is only served when the high queue is empty
            while (!lowServed) {
                boolean handledHigh = false;
                synchronized (high) {
                    if (!high.isEmpty()) {
                        high.removeFirst();
                        handledHigh = true;
                    }
                }
                if (handledHigh) {
                    continue;
                }
                synchronized (low) {
                    if (!low.isEmpty()) {
                        low.removeFirst();
                        lowServed = true;
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        low.add(1);
        Thread p = new Producer();
        Thread s = new Server();
        p.start();
        s.start();
        p.join();
        s.join();
    }
}

public class FairCounter {
    static final Object lock = new Object();
    static int counter = 0;

    static class Worker extends Thread {
        public void run() {
            for (int i = 0; i < 3; i++) {
                synchronized (lock) {
                    counter++;
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread a = new Worker();
        Thread b = new Worker();
        a.start();
        b.start();
        a.join();
        b.join();
        assert counter == 6;
    }
}
